local profile={[ [====[enemies]====] ]={[ [====[36AA99CCE5E60146]====] ]=true,[ [====[1A7FCDFF98C664B0]====] ]=true,[ [====[0AB7B92B131C228C]====] ]=true,[ [====[D9511E9F6BD62E3F]====] ]=true,[ [====[672F7DA17F3BA34A]====] ]=true,[ [====[8FF0A839830A7692]====] ]=true,[ [====[64090088502435DD]====] ]=true,[ [====[F540CA9D9D4A422E]====] ]=true,[ [====[EACEE39FA017B495]====] ]=true,[ [====[A6A68D8AF177F3A1]====] ]=true,[ [====[7ECE5304F868F6B3]====] ]=true,[ [====[9D8827FED763650E]====] ]=true,[ [====[96BA14C9EBB49CE1]====] ]=true,[ [====[AE63E525853D7044]====] ]=true,[ [====[F8131632AA867107]====] ]=true,[ [====[E8F19A0AA958E46D]====] ]=true,[ [====[CC188F0C80505C6C]====] ]=true,[ [====[905809A4C28D8A45]====] ]=true,[ [====[78E1497571012C47]====] ]=true,[ [====[20B9C7734DAEAD65]====] ]=true,[ [====[453FE22C634EB30F]====] ]=true,[ [====[DA40BB347C7447F2]====] ]=true,[ [====[604A794EC45BB820]====] ]=true,[ [====[67DC32DCA4F02D33]====] ]=true,[ [====[CCAE5264ACD591B7]====] ]=true,[ [====[A381A11C07D3EB94]====] ]=true,[ [====[CC7022FDD172089B]====] ]=true,[ [====[6021E22338333D88]====] ]=true,[ [====[6B202392F4AB605E]====] ]=true,[ [====[3AFF5FD7D5450B99]====] ]=true,[ [====[FD5247653C897803]====] ]=true,[ [====[3D0E03E2D574E1CA]====] ]=true,[ [====[5CA832447445C0BA]====] ]=true,[ [====[883401AF2A98A5F6]====] ]=true,[ [====[D1E990BAF22D5A52]====] ]=true,[ [====[51EEA86BF6997E4E]====] ]=true,[ [====[DFBACBD977A948DC]====] ]=true,[ [====[9A8A3AAE287B230C]====] ]=true,[ [====[AAB438596F5E8FD9]====] ]=true,[ [====[72A83E49CED6DB3D]====] ]=true,[ [====[F0B26FA9258128D3]====] ]=true,[ [====[BE39E313A1E46BB9]====] ]=true,[ [====[4E97FB073BDC7A4B]====] ]=true,[ [====[32541FC4EC7C9CDC]====] ]=true,[ [====[B2A6FA1E4284C7E6]====] ]=true,[ [====[10081ACEF6163EF6]====] ]=true,[ [====[D522FD4748D443A5]====] ]=true,[ [====[F79CD8BB654397DF]====] ]=true,[ [====[A35207C6F2150806]====] ]=true,[ [====[A1F37BF2A40FBDE4]====] ]=true,[ [====[B5DBC0C240C921AD]====] ]=true,[ [====[D5792F6856B06BA4]====] ]=true,[ [====[B056F8FC74ABA02D]====] ]=true,[ [====[7B48CACDBACB3881]====] ]=true,[ [====[AE57FCDB49F74E98]====] ]=true,[ [====[82A87AD8D595B2BA]====] ]=true,[ [====[09DFB04B2E578BC3]====] ]=true,[ [====[089833D2880D9E06]====] ]=true,[ [====[52018DEB9AB6827E]====] ]=true,[ [====[AF0F9B3A163787A5]====] ]=true,[ [====[856E9710E45E760F]====] ]=true,[ [====[B4ED319B39F5457B]====] ]=true,[ [====[A4552F97033392F4]====] ]=true,[ [====[D8CBC4A807A6D035]====] ]=true,[ [====[30CF04B2EC8C9BD4]====] ]=true,[ [====[FB9937035D652C43]====] ]=true,[ [====[257D805CAA7E10C0]====] ]=true,[ [====[4019623142351CB6]====] ]=true,[ [====[64BA5F030B114EC1]====] ]=true,[ [====[0002BA767DF856F3]====] ]=true,[ [====[A71AAFD82C6EBC92]====] ]=true,[ [====[215CE160A17BE4CD]====] ]=true,[ [====[1B5B9AC4F96B36E5]====] ]=true,[ [====[09FE0BE51A23396C]====] ]=true,[ [====[746A7F3BEDA32699]====] ]=true,[ [====[CBB1BA3366009C3A]====] ]=true,[ [====[1E66EE1F6F7FD00E]====] ]=true,[ [====[3E0537D606438FEA]====] ]=true,[ [====[E44EC9F9B3FE1D2A]====] ]=true,[ [====[6DAB2EADF5D8B692]====] ]=true,[ [====[1897BDD32105D2DC]====] ]=true,[ [====[137988CEA16458F7]====] ]=true,[ [====[32CDEADA234FB8DF]====] ]=true,[ [====[57EED0EAC346CD9D]====] ]=true,[ [====[FC8DEC78BE8AB47D]====] ]=true,[ [====[BE743B2FAA3A6E26]====] ]=true,[ [====[B92435FBF60F0748]====] ]=true,[ [====[F8B5A81A86D5D4EB]====] ]=true,[ [====[58B2B86C11369241]====] ]=true,[ [====[91EBD77931110AFC]====] ]=true,[ [====[9647B00CC3A9D36F]====] ]=true,[ [====[F66D0BAD8693779A]====] ]=true,[ [====[C9BCCCB0A54A82A4]====] ]=true,[ [====[E0353177F1329573]====] ]=true,[ [====[9076EEED17FCEE35]====] ]=true,[ [====[0ADC9F9173AD8E1D]====] ]=true,[ [====[44458A2C52B002FB]====] ]=true,[ [====[F1610AC48CDC5240]====] ]=true,[ [====[08E6FFC2474287BD]====] ]=true,[ [====[A05BD1EC67B3AC4C]====] ]=true,[ [====[1F0A91729C0004E0]====] ]=true,[ [====[DB964631BE1CF501]====] ]=true,[ [====[728421351D440EBC]====] ]=true,[ [====[9F57782F00E6ED20]====] ]=true,[ [====[E683D2CA5618D74A]====] ]=true,[ [====[2A12104F2853AE16]====] ]=true},[ [====[request_rva]====] ]=19526000,[ [====[request_code]====] ]=[====[]====],[ [====[status_type]====] ]=38,[ [====[buildup]====] ]=100,[ [====[cooldown_ms]====] ]=6000,[ [====[scan_ms]====] ]=250,[ [====[max_per_second]====] ]=4,[ [====[status_manager]====] ]=53634592,[ [====[health_manager]====] ]=53634696,[ [====[queue_global]====] ]=55037752,[ [====[queue_count]====] ]=2101556,[ [====[queue_capacity]====] ]=4096,[ [====[game]====] ]=53633856,[ [====[game_state]====] ]=705052,[ [====[game_mode]====] ]=53634720,[ [====[mode_count]====] ]=8,[ [====[mode_descriptor]====] ]=56,[ [====[descriptor_flags]====] ]=20,[ [====[status_registry]====] ]=58481744,[ [====[acid_refresh_ms]====] ]=5000,[ [====[max_acid_per_second]====] ]=4,[ [====[definitions]====] ]={{[ [====[id]====] ]=38,[ [====[label]====] ]=[====[Medium Stun]====],[ [====[sha]====] ]=[====[B4D89F43292164D2190C50BF13C738D4F747F1D70781E2C2E12E1D454ED69BED]====]},{[ [====[id]====] ]=55,[ [====[label]====] ]=[====[Acid Storm]====],[ [====[sha]====] ]=[====[AD60A2D5DB64F150C23A3912F9C59654309EE5AA65070134E4F95B2C2AE752F9]====]}}}
return function(make_api)
    if rawget(_G,'GasExposureInterruptV1')then return end
    local bit=require('bit')
    local state={active=false,status='Waiting for Gas Overhaul',requested=0,acid_requested=0,skipped_stunned=0,failures=0}
    _G.GasExposureInterruptV1=state
    local api=make_api();local previous=update
    local marks={};local world=nil;local cursor=0;local next_scan=0;local next_log=0
    local window=0;local requests=0;local acid_requests=0;local installed=false;local definitions={}
    local function u32(s,o)
        if not s or #s<o+4 then return nil end
        local a,b,c,d=s:byte(o+1,o+4);return a+b*256+c*65536+d*16777216
    end
    local function ptr(p)return api.pointer(api.read(p,8),0)end
    local function read32(p)return u32(api.read(p,4),0)end
    local function unhex(s)return(s:gsub('..',function(h)return string.char(tonumber(h,16))end))end
    local function key(desc)return string.format('%08X%08X',u32(desc,4),u32(desc,0))end
    local function log()
        pcall(function()
            local loader=rawget(_G,'CowboyBingusModLoader')
            local file=loader and loader.open_log and loader.open_log('GasExposureInterrupt.log')
            if file then
                file:write('Gas Enemy Effects test1\nstatus='..state.status..'\nrequested='..state.requested..'\nacid_requested='..state.acid_requested..'\nskipped_stunned='..state.skipped_stunned..'\nfailures='..state.failures..'\nMedium Stun38; buildup100; nominal3s; target cooldown6s\nAcid Storm55; buildup1; duration15s; refresh5s; gas-exposed enemies only\nHost only; no code patches\n')
                file:close()
            end
        end)
    end
    local function lookup(status,entity)
        local size=read32(status+0x12c8);local empty=read32(status+0x12cc);local multi=read32(status+0x12d0);local buckets=ptr(status+0x12c0)
        if not size or size<2 or size>65536 or not empty or not multi or not buckets then return end
        local low,high=multi%65536,math.floor(multi/65536)
        local start=(entity*low+((entity*high)%65536)*65536)%4294967296
        for i=0,size-1 do
            local entry=api.read(buckets+((start+i)%size)*8,8);if not entry then return end
            local id,index=u32(entry,0),u32(entry,4)
            if id==entity then if index<4096 then return index end;return end
            if id==empty then return end
        end
    end
    local function reset()marks={};world=nil;cursor=0;state.active=false end
    local function activity(status,index)
        local data=ptr(status+0x12e8);local bits=data and api.read(data+index*0x1228,128)
        if not bits or #bits~=128 then return end
        local exposed,confused,stun=false,false,false
        for zone=0,7 do
            local upper=u32(bits,zone*16+4)
            if bit.band(upper,0x3c00)~=0 then exposed=true end -- Gas42/43 or Gas Confusion44/45
            if bit.band(upper,0x3000)~=0 then confused=true end
            if bit.band(upper,0x1e0)~=0 then stun=true end -- existing Stun37..40
        end
        return exposed,confused,stun,bits,data
    end
    local function validate_definition(base,spec)
        local row=ptr(base+profile.status_registry+spec.id*8)
        assert(row,spec.label..' definition missing')
        if definitions[spec.id]then assert(row==definitions[spec.id],spec.label..' definition redirected')end
        local raw=assert(api.read(row,152),spec.label..' definition unreadable')
        assert(#raw==152 and u32(raw,0)==spec.id and api.sha256(raw:sub(1,8)..string.rep('\0',8)..raw:sub(17))==spec.sha,
            spec.label..' definition changed')
        definitions[spec.id]=row
    end
    local function step()
        local now=api.now();if now<next_scan then return end;next_scan=now+profile.scan_ms
        local gas=rawget(_G,'SterilizerArmorControlV1')
        if not gas or not gas.active then reset();state.status='Waiting for Gas Overhaul';return end
        local base=api.byte_pointer(api.module('game.dll'));assert(base~=nil,'Game module unavailable')
        local function code_guard()
            assert(api.read(base+profile.request_rva,#profile.request_code/2)==unhex(profile.request_code),'Status request code changed')
        end
        if not installed then
            code_guard();for _,spec in ipairs(profile.definitions)do validate_definition(base,spec)end
            installed=true
        end
        local game=ptr(base+profile.game);local mode=ptr(base+profile.game_mode);local desc=mode and ptr(mode+profile.mode_descriptor)
        if not game or read32(game+profile.game_state)~=4 or not mode or read32(mode+profile.mode_count)~=1 or not desc
          or bit.band(read32(desc+profile.descriptor_flags)or 0,1)==0 then
            reset();state.status='Waiting for a host mission';return
        end
        local health=ptr(base+profile.health_manager);local status=ptr(base+profile.status_manager)
        if not health or not status then reset();state.status='Waiting for live enemy data';return end
        local token=api.identity(mode)..':'..api.identity(desc)..':'..api.identity(health)..':'..api.identity(status)
        if world~=token then reset();world=token;window=now;requests=0;acid_requests=0 end
        local count=read32(health+4128);local capacity=read32(health+4112)
        local descriptors=ptr(health+4168);local records=ptr(health+4184)
        if not count or not capacity or count>capacity or capacity>4096 or not descriptors or not records then error('Unsupported health pool')end
        if now-window>=1000 then window=now;requests=0;acid_requests=0 end
        local visited=0
        while count>0 and visited<math.min(count,64)do
            cursor=cursor%count;local index=cursor;cursor=cursor+1;visited=visited+1
            local address=ptr(descriptors+index*8);local d=address and api.read(address,24)
            if d and profile.enemies[key(d)]and bit.band(u32(d,20),3)==1 then
                local entity=u32(d,8);local life=read32(records+index*440+412);local hp=read32(records+index*440+20)
                if entity and entity>0 and entity~=4294967295 and life==0 and hp and hp>0 and hp<2147483648 then
                    local si=lookup(status,entity);local status_descriptors=si and ptr(status+0x12d8)
                    local sd=status_descriptors and ptr(status_descriptors+si*8)
                    if sd and api.identity(sd)==api.identity(address)then
                        local exposed,confused,stunned,bits,active=activity(status,si)
                        local identity=entity..':'..api.identity(address)..':'..u32(d,12)..':'..u32(d,16)
                        local mark=marks[entity]
                        if mark and mark.identity~=identity then mark=nil;marks[entity]=nil end
                        if exposed then
                            if not mark then mark={identity=identity,next=now,acid_next=now};marks[entity]=mark end
                            mark.seen=now
                            local function submit(kind)
                                local queue=ptr(base+profile.queue_global);local queued=queue and read32(queue+profile.queue_count)
                                if not queued or queued>=profile.queue_capacity then return false end
                                assert(ptr(base+profile.health_manager)==health and ptr(base+profile.status_manager)==status,'Enemy pools changed')
                                assert(ptr(health+4168)==descriptors and ptr(health+4184)==records,'Health storage changed')
                                assert(ptr(descriptors+index*8)==address and api.read(address,24)==d and read32(records+index*440+412)==0 and read32(records+index*440+20)==hp,'Enemy lifetime changed')
                                assert(lookup(status,entity)==si and ptr(status+0x12d8)==status_descriptors and ptr(status_descriptors+si*8)==sd,'Status ownership changed')
                                code_guard();for _,spec in ipairs(profile.definitions)do validate_definition(base,spec)end
                                local again,confused_again,stun_again,current,current_data=activity(status,si)
                                if not again or current_data~=active or current~=bits or (kind==38 and (not confused_again or stun_again))then return false end
                                assert(ptr(base+profile.queue_global)==queue and read32(queue+profile.queue_count)==queued,'Status queue changed')
                                if kind==38 then api.request_stun(base+profile.request_rva,entity)
                                else api.request_acid(base+profile.request_rva,entity)end
                                local after=read32(queue+profile.queue_count)
                                assert(after==queued or after==queued+1,'Unexpected status queue mutation')
                                if kind==38 then
                                    mark.next=now+profile.cooldown_ms;requests=requests+1
                                    if after==queued+1 then state.requested=state.requested+1 end
                                else
                                    mark.acid_next=now+profile.acid_refresh_ms;acid_requests=acid_requests+1
                                    if after==queued+1 then state.acid_requested=state.acid_requested+1 end
                                end
                                return true
                            end
                            if now>=mark.acid_next and acid_requests<profile.max_acid_per_second then submit(55)end
                            if stunned then state.skipped_stunned=state.skipped_stunned+1 end
                            if confused and not stunned and now>=mark.next and requests<profile.max_per_second then submit(38)end
                        end
                    end
                end
            end
        end
        for id,mark in pairs(marks)do if now-mark.seen>30000 then marks[id]=nil end end
        state.active=true;state.status='Ready: host-only enemy gas Acid Storm15s/refresh5s; Medium Stun3s/cooldown6s'
    end
    local disabled=false
    local function tick()
        if disabled then return end
        local ok,why=pcall(step)
        if not ok then disabled=true;state.active=false;state.failures=state.failures+1;state.status='Refused: '..tostring(why);log()end
        local now=api.now();if not disabled and now>=next_log then log();next_log=now+2000 end
    end
    local function finish(...)tick();return ... end
    update=function(...)if previous then return finish(previous(...))end;tick()end
    log()
end
